//! Logical processing contracts of each selected board entrypoint: key count,
//! the sides the entrypoint passes to the processor, and its encoder action
//! slots. Key counts and sides come from each default keymap at compile time.
//! No MCU imports, display geometry, GPIO wiring or live identity is implied.
//!
//! This file is compiled inside the portable default keymap module generated by
//! `src/firmware/build.zig`, next to the generated `default_keymaps.zig`.
const std = @import("std");
const core = @import("zigmkay").core;
const boards = @import("default_keymaps.zig").boards;
const profiles = @import("default_keymaps.zig").profiles;

pub const version: u16 = 2;

pub const Entry = struct {
    selector: []const u8,
    key_count: usize,
    sides: []const core.Side,
    /// Action slots, not encoder devices: CW and CCW have separate indexes.
    /// Every entrypoint wires knob n (from 0) to slot 2n clockwise and slot
    /// 2n + 1 counter-clockwise; the editor names slots by this convention.
    /// A knob's push button is a matrix key and has no slot.
    encoder_actions: usize,
};

/// The reviewed entrypoints are listed in `boards.zig` (`bindings`), next to
/// the inventory, which offers only boards that have one.
const binding_of = @import("boards.zig").binding;

fn unassignedSides(comptime count: usize) []const core.Side {
    return &struct {
        const value: [count]core.Side = @splat(.X);
    }.value;
}

pub const entries = blk: {
    @setEvalBranchQuota(100_000);
    if (profiles.len != boards.entries.len) {
        @compileError(
            "Default keymap profiles do not match the board inventory",
        );
    }
    var result: [boards.entries.len]Entry = undefined;
    for (boards.entries, profiles, 0..) |board, Profile, index| {
        const binding = binding_of(board.root_source_file) orelse @compileError(
            "Missing processing descriptor for " ++ board.root_source_file,
        );
        const key_count = @typeInfo(@typeInfo(@TypeOf(Profile.keymap)).array.child).array.len;
        if (@hasDecl(Profile, "key_count") and Profile.key_count != key_count)
            @compileError("Default keymap key_count differs from its layer width: " ++ board.default_keymap);
        const sides: []const core.Side = switch (binding.sides) {
            .keymap => &Profile.sides,
            .unassigned => unassignedSides(key_count),
        };
        if (sides.len != key_count) {
            @compileError(
                "Default keymap sides differ from its key count: " ++ board.default_keymap,
            );
        }
        result[index] = .{
            .selector = board.name,
            .key_count = key_count,
            .sides = sides,
            .encoder_actions = binding.encoder_actions,
        };
    }
    break :blk result;
};

pub fn find(selector: []const u8) ?*const Entry {
    for (&entries) |*entry| if (std.mem.eql(u8, selector, entry.selector)) return entry;
    return null;
}

test "processing inventory covers every selector and keeps encoder slot indexes" {
    try std.testing.expectEqual(boards.entries.len, entries.len);
    for (entries) |entry| {
        try std.testing.expectEqualStrings(entry.selector, find(entry.selector).?.selector);
        try std.testing.expectEqual(entry.key_count, entry.sides.len);
        try std.testing.expect(entry.key_count > 0 and entry.key_count <= 127);
    }
    try std.testing.expectEqual(@as(usize, 4), find("tuckytwotimes").?.encoder_actions);
    try std.testing.expectEqual(@as(usize, 2), find("molekula").?.encoder_actions);
    try std.testing.expectEqual(@as(usize, 34), find("lk8").?.key_count);
    try std.testing.expectEqualSlices(core.Side, find("lk7").?.sides, find("lk8").?.sides);
    for (find("dasbob").?.sides) |side| try std.testing.expectEqual(core.Side.X, side);
    try std.testing.expect(find("encoder_demo") == null);
    try std.testing.expect(find("yak") == null);
}
